// Check if a password can be drawn in a single stroke
// Rules: 
// - The password consists of digits 0-9
// - It must be possible to draw the sequence on a standard phone keypad
//   without lifting the pen, moving only horizontally or vertically
//   between adjacent keys (no diagonals).
// - The path can revisit keys, but each move must be to an adjacent key.

bool canFormSingleStroke(const string& s) {
    if (s.empty()) return false;

    // Define keypad positions (row, col) for digits 0-9
    // Standard phone keypad layout:
    // 1 2 3
    // 4 5 6
    // 7 8 9
    // 0 (usually below 8, but let's place it at (3,1))
    int pos[10][2] = {
        {3, 1}, // 0
        {0, 0}, // 1
        {0, 1}, // 2
        {0, 2}, // 3
        {1, 0}, // 4
        {1, 1}, // 5
        {1, 2}, // 6
        {2, 0}, // 7
        {2, 1}, // 8
        {2, 2}  // 9
    };

    for (size_t i = 1; i < s.length(); ++i) {
        int prev = s[i-1] - '0';
        int cur = s[i] - '0';
        if (prev < 0 || prev > 9 || cur < 0 || cur > 9) return false;
        int dr = abs(pos[prev][0] - pos[cur][0]);
        int dc = abs(pos[prev][1] - pos[cur][1]);
        // Must be adjacent (Manhattan distance 1, no diagonals)
        if (!((dr == 1 && dc == 0) || (dr == 0 && dc == 1))) {
            return false;
        }
    }
    return true;
}

