// Union-Find for connectivity check
struct UF {
    int parent[128];
    void init() { for(int i=0;i<128;i++) parent[i]=i; }
    int find(int x) { return parent[x]==x?x:parent[x]=find(parent[x]); }
    void unite(int a, int b) { parent[find(a)]=find(b); }
    bool same(int a, int b) { return find(a)==find(b); }
};

bool isSingleStroke(const string& s) {
    if(s.size() == 0) return true;
    if(s.size() == 1) return true;

    // Build adjacency
    int degree[128] = {};
    bool used[128] = {};
    UF uf;
    uf.init();

    for(int i = 0; i < (int)s.size(); i++) {
        used[(int)s[i]] = true;
    }

    for(int i = 0; i+1 < (int)s.size(); i++) {
        int a = s[i], b = s[i+1];
        degree[a]++;
        degree[b]++;
        uf.unite(a, b);
    }

    // Check connectivity: all used nodes should be in same component
    int root = -1;
    for(int i = 0; i < 128; i++) {
        if(used[i]) {
            if(root == -1) root = uf.find(i);
            else if(uf.find(i) != root) return false;
        }
    }

    // Count odd degree vertices
    int oddCount = 0;
    for(int i = 0; i < 128; i++) {
        if(used[i] && degree[i] % 2 == 1) oddCount++;
    }

    return oddCount == 0 || oddCount == 2;
}

