// Check if a password can be formed in a single stroke
int is_single_stroke(const char *password) {
    int len = strlen(password);
    if (len == 0) return 0;

    // Check if all characters are digits
    for (int i = 0; i < len; i++) {
        if (!isdigit(password[i])) {
            return 0;
        }
    }

    // For a single stroke, the password must:
    // 1. Consist only of digits (already checked)
    // 2. Be formed by moving in one continuous stroke on a numeric keypad
    //    where you can move to adjacent keys (including diagonally)
    //    and each key can be used multiple times

    // Keypad layout:
    // 7 8 9
    // 4 5 6
    // 1 2 3
    //   0

    // Check if consecutive digits are adjacent on the keypad
    for (int i = 0; i < len - 1; i++) {
        int curr = password[i] - '0';
        int next = password[i+1] - '0';

        // Get coordinates for current digit
        int curr_row, curr_col;
        if (curr == 0) {
            curr_row = 3;
            curr_col = 1;
        } else {
            curr_row = 2 - (curr - 1) / 3;
            curr_col = (curr - 1) % 3;
        }

        // Get coordinates for next digit
        int next_row, next_col;
        if (next == 0) {
            next_row = 3;
            next_col = 1;
        } else {
            next_row = 2 - (next - 1) / 3;
            next_col = (next - 1) % 3;
        }

        // Calculate Manhattan distance
        int row_diff = curr_row - next_row;
        if (row_diff < 0) row_diff = -row_diff;
        int col_diff = curr_col - next_col;
        if (col_diff < 0) col_diff = -col_diff;

        // Adjacent if distance is 0 (same key) or 1 (adjacent including diagonal)
        if (row_diff > 1 || col_diff > 1) {
            return 0;
        }
    }

    return 1;
}

