def can_single_stroke(password):
    if len(password) <= 1:
        return True

    degree = defaultdict(int)

    for i in range(len(password) - 1):
        u = password[i]
        v = password[i+1]
        degree[u] += 1
        degree[v] += 1

    # Check odd degree vertices
    odd_count = sum(1 for v in degree if degree[v] % 2 == 1)

    if odd_count != 0 and odd_count != 2:
        return False

    # Check connectivity using union-find
    parent = {}
    def find(x):
        if x not in parent:
            parent[x] = x
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py

    for i in range(len(password) - 1):
        union(password[i], password[i+1])

    roots = set(find(v) for v in degree)
    if len(roots) > 1:
        return False

    return True

