def is_single_stroke(s: str) -> bool:
    n = len(s)
    if n <= 1:
        return True

    # Adjacent keys on the keypad
    adj = {
        '1': {'2', '4', '5'},
        '2': {'1', '3', '4', '5', '6'},
        '3': {'2', '5', '6'},
        '4': {'1', '2', '5', '7', '8'},
        '5': {'1', '2', '3', '4', '6', '7', '8', '9'},
        '6': {'2', '3', '5', '8', '9'},
        '7': {'4', '5', '8', '0'},
        '8': {'4', '5', '6', '7', '9', '0'},
        '9': {'5', '6', '8', '0'},
        '0': {'7', '8', '9'},
    }

    used = set(s)
    visited = {s[0]}

    for i in range(1, n):
        a, b = s[i - 1], s[i]
        if a == b:
            return False
        if b not in adj[a]:
            return False
        if b in visited:
            return False
        visited.add(b)

    # All used keys must form one connected component under adjacency
    stack = [s[0]]
    seen = {s[0]}
    while stack:
        v = stack.pop()
        for to in adj[v]:
            if to in used and to not in seen:
                seen.add(to)
                stack.append(to)

    return seen == used

