public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line;
        List<String> candidates = new ArrayList<>();

        while ((line = reader.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;
            candidates.add(line);
        }

        for (String password : candidates) {
            if (isSingleStroke(password)) {
                System.out.println(password);
            }
        }
    }

    private static boolean isSingleStroke(String s) {
        if (s == null || s.isEmpty()) return false;

        // Define the keypad layout as a 3x4 grid
        // Row 0: 1 2 3
        // Row 1: 4 5 6
        // Row 2: 7 8 9
        // Row 3: * 0 #
        char[][] keypad = {
            {'1', '2', '3'},
            {'4', '5', '6'},
            {'7', '8', '9'},
            {'*', '0', '#'}
        };

        // Map each character to its position
        int[][] pos = new int[256][2];
        for (int i = 0; i < 256; i++) {
            pos[i][0] = -1;
            pos[i][1] = -1;
        }
        for (int r = 0; r < 4; r++) {
            for (int c = 0; c < 3; c++) {
                char ch = keypad[r][c];
                pos[ch][0] = r;
                pos[ch][1] = c;
            }
        }

        // Check first character exists on keypad
        char first = s.charAt(0);
        if (pos[first][0] == -1) return false;

        // For a single character password, it's always valid
        if (s.length() == 1) return true;

        // Determine initial direction
        char second = s.charAt(1);
        if (pos[second][0] == -1) return false;

        int dr = pos[second][0] - pos[first][0];
        int dc = pos[second][1] - pos[first][1];

        // Direction must be one of the 8 possible moves (including staying, but staying is valid only for length 1)
        if (dr == 0 && dc == 0) return false; // can't stay on same key for consecutive presses

        // Normalize direction to unit vector
        int gcd = gcd(Math.abs(dr), Math.abs(dc));
        int stepR = dr / gcd;
        int stepC = dc / gcd;

        // Check that the direction is one of the 8 allowed (including zero for one key)
        if (Math.abs(stepR) > 1 || Math.abs(stepC) > 1) return false;
        if (stepR == 0 && stepC == 0) return false;

        // Now verify all consecutive pairs follow the same direction
        for (int i = 1; i < s.length() - 1; i++) {
            char curr = s.charAt(i);
            char next = s.charAt(i + 1);
            if (pos[curr][0] == -1 || pos[next][0] == -1) return false;

            int currDr = pos[next][0] - pos[curr][0];
            int currDc = pos[next][1] - pos[curr][1];

            if (currDr == 0 && currDc == 0) return false;

            int currGcd = gcd(Math.abs(currDr), Math.abs(currDc));
            int currStepR = currDr / currGcd;
            int currStepC = currDc / currGcd;

            if (currStepR != stepR || currStepC != stepC) return false;
        }

        // Additionally, the path must be a straight line: all intermediate keys between first and last must be pressed
        // This is automatically satisfied if the direction is consistent and we check that every key along the line exists
        // But we must ensure no key is skipped. Actually, if the direction is consistent, the path is a straight line.
        // However, the problem might require that the stroke goes through intermediate keys.
        // For a straight line with step (stepR, stepC), the keys in between must be exactly the ones at positions
        // first + k*step for k=1..(gcd-1). Since we are given the password, we need to verify that those intermediate keys
        // are actually present in order. This is already checked by the loop above.

        // Also need to ensure that the stroke does not go outside the keypad
        // Check each key in the sequence is within bounds
        int r = pos[first][0];
        int c = pos[first][1];
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (r != pos[ch][0] || c != pos[ch][1]) return false;
            r += stepR;
            c += stepC;
        }

        return true;
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}

