        int[] degree = new int[256];
        parent = new int[256];
        for (int i = 0; i < 256; i++) parent[i] = i;

        Set<Character> used = new HashSet<>();

        for (int i = 0; i < s.length() - 1; i++) {
            char a = s.charAt(i);
            char b = s.charAt(i + 1);
            used.add(a);
            used.add(b);
            degree[a]++;
            degree[b]++;
            union(a, b);
        }
        used.add(s.charAt(0));
        if (s.length() > 1) used.add(s.charAt(s.length()-1));

        // Check connectivity
        if (used.size() > 1) {
            char first = used.iterator().next();
            int root = find(first);
            for (char c : used) {
                if (find(c) != root) return false;
            }
        }

        // Count odd degree vertices
        int oddCount = 0;
        for (char c : used) {
            if (degree[c] % 2 != 0) oddCount++;
        }

        return oddCount == 0 || oddCount == 2;
    }
