public class Main {
    static final class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c != -1 && Character.isWhitespace(c));
            if (c == -1) return null;
            while (c != -1 && !Character.isWhitespace(c)) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        // Keyboard rows for one-stroke typing
        String row1 = "qwertyuiop";
        String row2 = "asdfghjkl";
        String row3 = "zxcvbnm";

        int[] belong = new int[256];
        for (char c : row1.toCharArray()) {
            belong[c] = 1;
            belong[Character.toUpperCase(c)] = 1;
        }
        for (char c : row2.toCharArray()) {
            belong[c] = 2;
            belong[Character.toUpperCase(c)] = 2;
        }
        for (char c : row3.toCharArray()) {
            belong[c] = 3;
            belong[Character.toUpperCase(c)] = 3;
        }

        // The statement says there are 1000 candidate passwords.
        // To be robust, if the first token is an integer, use it as count.
        // Otherwise, treat all tokens as candidate strings.
        String first = fs.next();
        if (first == null) {
            System.out.print("");
            return;
        }

        List<String> words = new ArrayList<>();
        boolean firstIsInt = true;
        int n = 0;
        try {
            n = Integer.parseInt(first);
        } catch (NumberFormatException e) {
            firstIsInt = false;
        }

        if (firstIsInt) {
            for (int i = 0; i < n; i++) {
                String s = fs.next();
                if (s == null) break;
                words.add(s);
            }
        } else {
            words.add(first);
            String s;
            while ((s = fs.next()) != null) words.add(s);
        }

        for (String s : words) {
            if (isOneStroke(s, belong)) {
                out.append(s).append('\n');
            }
        }

        System.out.print(out.toString());
    }

    static boolean isOneStroke(String s, int[] belong) {
        if (s.isEmpty()) return true;
        int row = belong[s.charAt(0)];
        if (row == 0) return false;
        for (int i = 1; i < s.length(); i++) {
            if (belong[s.charAt(i)] != row) return false;
        }
        return true;
    }
}
